import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.oeh4wjV1.js";const u=JSON.parse('{"title":"Feudalism","description":"","frontmatter":{},"headers":[],"relativePath":"boxed-sets/feudalism.md","filePath":"boxed-sets/feudalism.md","lastUpdated":1792425987000}'),i={name:"boxed-sets/feudalism.md"};function o(s,e,l,h,d,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="feudalism" tabindex="-1">Feudalism <a class="header-anchor" href="#feudalism" aria-label="Permalink to &quot;Feudalism&quot;">​</a></h1><p><a href="./">All boxed sets</a> · <a href="./../formats/bang-like/">BANG-like format family</a></p><div class="warning custom-block"><p class="custom-block-title">Draft — not yet a complete playable box</p><p>The recurring-monarchy concept below is recorded. The specific base ruleset, role distribution, and victory conditions have not been chosen. This page does not silently adopt one source&#39;s roles or invent a finished ruleset.</p></div><h2 id="concept" tabindex="-1">Concept <a class="header-anchor" href="#concept" aria-label="Permalink to &quot;Concept&quot;">​</a></h2><p>Feudalism is a hidden-role game-night box built around the monarch mechanic. Players can fight over the crown, but power returns to the King until the group breaks that structure. A Renegade-style role is intended to win by properly dethroning the King; what qualifies as dethroning still needs a rule.</p><h2 id="base-ruleset" tabindex="-1">Base ruleset <a class="header-anchor" href="#base-ruleset" aria-label="Permalink to &quot;Base ruleset&quot;">​</a></h2><p><strong>Not yet selected.</strong> Choose a specific version before this box can be played:</p><ul><li><a href="./../formats/bang-like/variants/bang-magic.html">BANG! Magic</a>: Sheriff, Deputies, Outlaws, and Renegade.</li><li><a href="./../formats/bang-like/variants/kingdoms.html">Kingdoms</a>: King, Knight, Bandits, Assassin, and optional Usurper.</li><li><a href="./../formats/bang-like/variants/kingdom-bang-edh.html">Kingdom / BANG EDH</a>: Emperor, Guard, Assassins, and Rogue.</li><li><a href="./../formats/bang-like/variants/treachery.html">MTG Treachery</a>: custom identities with unveil abilities.</li></ul><p>These versions have different victory and reveal rules. Choosing one is a design decision, not merely renaming its leader to King.</p><h2 id="recorded-additional-rules" tabindex="-1">Recorded additional rules <a class="header-anchor" href="#recorded-additional-rules" aria-label="Permalink to &quot;Recorded additional rules&quot;">​</a></h2><h3 id="f1-starting-monarchy" tabindex="-1">F1. Starting monarchy <a class="header-anchor" href="#f1-starting-monarchy" aria-label="Permalink to &quot;F1. Starting monarchy&quot;">​</a></h3><p>The player with the King role starts the game as the monarch.</p><h3 id="f2-the-crown-returns" tabindex="-1">F2. The crown returns <a class="header-anchor" href="#f2-the-crown-returns" aria-label="Permalink to &quot;F2. The crown returns&quot;">​</a></h3><p>At the start of the King&#39;s turn, if the King is not the monarch, the King becomes the monarch.</p><p>The original concept says “at the start of the King&#39;s turn.” Before playtesting, decide whether this happens before untapping or as a triggered ability at the beginning of upkeep. Those timings behave differently; no timing has been chosen here.</p><h3 id="f3-ordinary-monarchy" tabindex="-1">F3. Ordinary monarchy <a class="header-anchor" href="#f3-ordinary-monarchy" aria-label="Permalink to &quot;F3. Ordinary monarchy&quot;">​</a></h3><p>The <strong>King role</strong> and <strong>being the monarch</strong> are different things. The recorded rule changes who has the monarch designation; it does not say that taking the monarch designation changes a hidden role.</p><p>Unless the completed box explicitly replaces them, the ordinary monarch rules apply:</p><ul><li>Exactly one player is the monarch once the designation has entered the game. A new monarch replaces the previous one.</li><li>At the beginning of the monarch&#39;s end step, the monarch&#39;s inherent ability triggers and that player draws a card when it resolves.</li><li>When a creature deals combat damage to the monarch, an inherent ability triggers; when it resolves, that creature&#39;s controller becomes the monarch.</li><li>If the monarch leaves the game, the active player becomes the monarch. If the active player is leaving too, the next player in turn order becomes the monarch.</li></ul><p>These are ordinary monarch rules, checked against the <a href="https://scryfall.com/card/msc/140/palace-jailer" target="_blank" rel="noreferrer">official rulings for Palace Jailer</a>. They do not define Feudalism&#39;s dethroning victory condition.</p><h2 id="replacement-rules-still-to-design" tabindex="-1">Replacement rules still to design <a class="header-anchor" href="#replacement-rules-still-to-design" aria-label="Permalink to &quot;Replacement rules still to design&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule area</th><th>Required decision</th></tr></thead><tbody><tr><td>Player count and roles</td><td>Name every role and give an exact distribution for each supported player count.</td></tr><tr><td>Victory</td><td>State every role&#39;s win/loss condition, what dethroning means, and which result takes precedence if conditions coincide.</td></tr><tr><td>King bonuses</td><td>Decide starting life, opening hand size, and any bonus beyond recurring monarchy.</td></tr><tr><td>Crown timing</td><td>Choose the exact timing and whether players can respond to F2.</td></tr><tr><td>Revealing roles</td><td>Decide whether becoming monarch reveals a role or triggers any role-specific ability.</td></tr><tr><td>Leaving the game</td><td>Decide how eliminating or replacing the King affects F2, the remaining roles, and the end of the game.</td></tr></tbody></table><h2 id="deck-and-component-requirements" tabindex="-1">Deck and component requirements <a class="header-anchor" href="#deck-and-component-requirements" aria-label="Permalink to &quot;Deck and component requirements&quot;">​</a></h2><p>The recorded deck requirements are:</p><ul><li>Every deck features monarch cards or cards that care about becoming the monarch.</li><li>Every deck works with any role it might receive.</li><li>The decks encourage contesting the crown while leaving the King vulnerable to pressure.</li></ul><p>Deck count, decklists, supported player counts, role cards, and starting-life aids remain to be specified. Include a monarch marker and a reminder for F2 when preparing the first playtest kit.</p><h2 id="optional-rules" tabindex="-1">Optional rules <a class="header-anchor" href="#optional-rules" aria-label="Permalink to &quot;Optional rules&quot;">​</a></h2><p>No optional module has been finalized. Proposed role triggers, alternate King bonuses, or different crown rules belong here once their complete procedures are written down.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>The original concept is preserved in this repository&#39;s history. Its source family is documented under <a href="./../formats/bang-like/">BANG-like hidden roles</a> and <a href="./../sources/">source notes</a>.</p>',30)])])}const p=a(i,[["render",o]]);export{u as __pageData,p as default};
